//! Flowchart creation and navigation parity (ex-534).
//!
//! `tests/fixtures/flowchart.json` is upstream's own
//! `packages/element/src/flowchart.ts` at the pinned commit, generated by
//! `tools/goldens/flowchart-fixtures.mjs`: `findNearestFreeSlot` and
//! `placeCluster` on seeded inputs, `FlowChartCreator.createNodes` step by
//! step on hand-written and seeded random scenes (the pending nodes and
//! arrows it builds, whole, and the scene elements it changes),
//! `FlowChartNavigator.exploreByDirection` step by step on flowcharts
//! grown by upstream's creator, and `isNodeInFlowchart`. Elements are
//! compared whole, number for number, ids, seeds and version nonces
//! included: the environment is upstream's test mode after `reseed(1)`.

use excali_core::element::Element;
use excali_core::fractional_index::ChangeStamp;
use excali_core::restore::{RestoreEnv, TestEnv};
use excali_editor::flowchart::{
    find_nearest_free_slot, is_node_in_flowchart, place_cluster, FlowChartCreator,
    FlowChartNavigator, FlowchartAppState, Interval,
};
use excali_editor::keyboard::LinkDirection;
use excali_editor::scene::{MutationEnv, Scene};
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/flowchart.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("flowchart.json parses")
}

fn element(value: &Value) -> Element {
    Element::from_map(value.as_object().expect("an element").clone())
        .expect("an element upstream built")
}

fn elements(value: &Value) -> Vec<Element> {
    value
        .as_array()
        .expect("elements")
        .iter()
        .map(element)
        .collect()
}

fn num(v: &Value) -> f64 {
    v.as_f64().unwrap_or_else(|| panic!("a number, got {v}"))
}

fn direction(v: &Value) -> LinkDirection {
    match v.as_str().expect("a direction") {
        "up" => LinkDirection::Up,
        "right" => LinkDirection::Right,
        "down" => LinkDirection::Down,
        "left" => LinkDirection::Left,
        other => panic!("a direction, got {other}"),
    }
}

/// Upstream's test mode after `reseed(1)`: ids `id0`, `id1`, ...,
/// timestamps 1, and every `randomInteger()` (seeds and version nonces)
/// from roughjs' `Random(1)`, in upstream's order.
struct Env(TestEnv);

impl RestoreEnv for Env {
    fn now(&mut self) -> f64 {
        1.0
    }

    fn random_id(&mut self) -> String {
        self.0.random_id()
    }

    fn random_integer(&mut self) -> f64 {
        self.0.random_integer()
    }
}

impl MutationEnv for Env {
    fn random_integer(&mut self) -> f64 {
        self.0.random_integer()
    }

    fn now(&mut self) -> f64 {
        1.0
    }
}

impl ChangeStamp for Env {
    fn version_nonce(&mut self) -> f64 {
        self.0.random_integer()
    }

    fn updated(&mut self) -> f64 {
        1.0
    }
}

fn same_elements(got: &[Element], want: &[Element], context: &str) {
    assert_eq!(
        got.iter().map(|e| e.base.id.as_str()).collect::<Vec<_>>(),
        want.iter().map(|e| e.base.id.as_str()).collect::<Vec<_>>(),
        "{context}: ids"
    );
    for (g, w) in got.iter().zip(want) {
        assert_eq!(g.to_map(), w.to_map(), "{context}: element {}", w.base.id);
    }
}

#[test]
fn find_nearest_free_slot_matches_upstream() {
    let f = fixture();
    let cases = f["slots"].as_array().unwrap();
    assert!(cases.len() >= 40);
    for (i, c) in cases.iter().enumerate() {
        let occupied: Vec<Interval> = c["occupied"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| Interval {
                start: num(&o["start"]),
                end: num(&o["end"]),
            })
            .collect();
        let got = find_nearest_free_slot(num(&c["ideal"]), num(&c["size"]), &occupied);
        assert_eq!(got, num(&c["result"]), "slot case {i}: {c}");
    }
}

#[test]
fn place_cluster_matches_upstream() {
    let f = fixture();
    let cases = f["clusters"].as_array().unwrap();
    assert!(cases.len() >= 40);
    for (i, c) in cases.iter().enumerate() {
        let parent = element(&c["parent"]);
        let obstacles: Vec<[f64; 4]> = c["obstacles"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| [num(&b[0]), num(&b[1]), num(&b[2]), num(&b[3])])
            .collect();
        let sticky = c["sticky"].as_f64();
        let count = c["count"].as_u64().unwrap() as usize;
        let got = place_cluster(
            &parent,
            direction(&c["direction"]),
            count,
            &obstacles,
            sticky,
        );
        let want: Vec<[f64; 2]> = c["result"]["positions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| [num(&p["x"]), num(&p["y"])])
            .collect();
        assert_eq!(got.positions, want, "cluster case {i}");
        assert_eq!(
            got.cross_start,
            num(&c["result"]["crossStart"]),
            "cluster case {i}"
        );
    }
}

#[test]
fn create_nodes_matches_upstream() {
    let f = fixture();
    let cases = f["create"].as_array().unwrap();
    assert!(cases.len() >= 50);
    let mut framed = 0;
    for c in cases {
        let id = c["id"].as_str().unwrap();
        let initial = elements(&c["elements"]);
        let mut scene = Scene::new(initial.clone());
        let app = FlowchartAppState {
            current_item_end_arrowhead: c["appState"]["currentItemEndArrowhead"].clone(),
            zoom: num(&c["appState"]["zoom"]),
        };
        let mut env = Env(TestEnv::default());
        let mut creator = FlowChartCreator::default();
        for (s, step) in c["steps"].as_array().unwrap().iter().enumerate() {
            let context = format!("{id} step {s}");
            if step["op"] == "clear" {
                creator.clear();
                assert!(!creator.is_creating_chart, "{context}");
                assert!(creator.pending_nodes.is_none(), "{context}");
                continue;
            }
            creator.create_nodes(
                step["start"].as_str().unwrap(),
                &app,
                direction(&step["direction"]),
                &mut scene,
                &mut env,
            );
            assert!(creator.is_creating_chart, "{context}");
            let pending = creator.pending_nodes.clone().expect("pending nodes");
            let want = elements(&step["pending"]);
            framed += want.iter().filter(|e| e.base.frame_id.is_some()).count();
            same_elements(&pending, &want, &format!("{context} pending"));
            let changed: Vec<Element> = scene
                .elements()
                .iter()
                .filter(|e| !initial.contains(e))
                .cloned()
                .collect();
            same_elements(
                &changed,
                &elements(&step["changed"]),
                &format!("{context} scene"),
            );
        }
    }
    assert!(framed > 0, "the frame rule is exercised");
}

#[test]
fn explore_by_direction_matches_upstream() {
    let f = fixture();
    let cases = f["navigate"].as_array().unwrap();
    assert!(cases.len() >= 40);
    let mut found = 0;
    for c in cases {
        let id = c["id"].as_str().unwrap();
        let scene = Scene::new(elements(&c["elements"]));
        let mut navigator = FlowChartNavigator::default();
        for (s, step) in c["steps"].as_array().unwrap().iter().enumerate() {
            if step["op"] == "clear" {
                navigator.clear();
                assert!(!navigator.is_exploring, "{id} step {s}");
                continue;
            }
            let got = navigator.explore_by_direction(
                step["from"].as_str().unwrap(),
                &scene,
                direction(&step["direction"]),
            );
            let want = step["result"].as_str().map(str::to_owned);
            found += usize::from(want.is_some());
            assert_eq!(got, want, "{id} step {s}: {step}");
            assert_eq!(
                navigator.is_exploring,
                step["isExploring"].as_bool().unwrap(),
                "{id} step {s}: isExploring"
            );
        }
    }
    assert!(found > 100, "the walk finds nodes");
}

#[test]
fn is_node_in_flowchart_matches_upstream() {
    let f = fixture();
    for (i, c) in f["inFlowchart"].as_array().unwrap().iter().enumerate() {
        let scene = Scene::new(elements(&c["elements"]));
        let node = scene.get(c["node"].as_str().unwrap()).unwrap();
        assert_eq!(
            is_node_in_flowchart(node, &scene),
            c["result"].as_bool().unwrap(),
            "case {i}"
        );
    }
}

/// `AppFlowchart.handleKeyEvent`'s operations for the keyboard's effects
/// (`App.flowchart.ts:53-178`): Ctrl+Arrow twice keeps two pending nodes
/// and arrows, releasing Ctrl commits them, Alt+Arrow walks and releasing
/// Alt ends the walk.
#[test]
fn app_flowchart_answers_the_keyboard_effects() {
    use excali_editor::flowchart::{AppFlowchart, FlowchartOperation};
    use excali_editor::keyboard::{FlowchartKeys, KeyEffect};

    let f = fixture();
    let case = f["create"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["id"] == "grow-right")
        .unwrap();
    let mut scene = Scene::new(elements(&case["elements"]));
    let app_state = excali_core::app_state::AppState::default();
    let mut keys = FlowchartKeys::default();
    let mut env = Env(TestEnv::default());
    let mut app = AppFlowchart::default();
    let create = KeyEffect::FlowchartCreate {
        start: Some("a".into()),
        direction: LinkDirection::Right,
    };
    for _ in 0..2 {
        let op = app.answer(&create, &mut scene, &app_state, &mut keys, &mut env);
        assert!(matches!(op, Some(FlowchartOperation::Creating { .. })));
    }
    assert!(keys.is_creating_chart);
    // the same nodes as upstream's second press
    let want = elements(&case["steps"][1]["pending"]);
    let ids = |v: &[Element]| v.iter().map(|e| e.base.id.clone()).collect::<Vec<_>>();
    assert_eq!(ids(app.pending_nodes()), ids(&want));

    // Ctrl+Arrow with nothing to start from still reports the pending nodes
    let op = app.answer(
        &KeyEffect::FlowchartCreate {
            start: None,
            direction: LinkDirection::Right,
        },
        &mut scene,
        &app_state,
        &mut keys,
        &mut env,
    );
    assert_eq!(
        op,
        Some(FlowchartOperation::Creating {
            pending: app.pending_nodes().to_vec()
        })
    );

    // the keyboard lowers the flag on the keyup, then asks for the commit
    keys.is_creating_chart = false;
    let op = app.answer(
        &KeyEffect::FlowchartCommit,
        &mut scene,
        &app_state,
        &mut keys,
        &mut env,
    );
    let Some(FlowchartOperation::Committed { nodes }) = op else {
        panic!("committed, got {op:?}");
    };
    assert_eq!(ids(&nodes), ids(&want));
    assert!(app.pending_nodes().is_empty());
    assert!(!keys.is_creating_chart);

    // Escape drops a new session's pending nodes
    app.answer(&create, &mut scene, &app_state, &mut keys, &mut env);
    let op = app.answer(
        &KeyEffect::FlowchartCanceled,
        &mut scene,
        &app_state,
        &mut keys,
        &mut env,
    );
    assert_eq!(op, Some(FlowchartOperation::Canceled));
    assert!(app.pending_nodes().is_empty());

    // the walk: the committed nodes are in the scene now
    let mut all = scene.elements().to_vec();
    all.extend(nodes.iter().cloned());
    let mut scene = Scene::new(all);
    let navigate = |from: &str| KeyEffect::FlowchartNavigate {
        from: from.into(),
        direction: LinkDirection::Right,
    };
    let op = app.answer(&navigate("a"), &mut scene, &app_state, &mut keys, &mut env);
    assert_eq!(
        op,
        Some(FlowchartOperation::Navigating {
            node_id: Some(nodes[0].base.id.clone())
        })
    );
    assert!(keys.is_exploring);
    let op = app.answer(
        &navigate(&nodes[0].base.id),
        &mut scene,
        &app_state,
        &mut keys,
        &mut env,
    );
    assert_eq!(
        op,
        Some(FlowchartOperation::Navigating {
            node_id: Some(nodes[2].base.id.clone())
        })
    );
    // Alt released
    keys.is_exploring = false;
    let op = app.answer(
        &KeyEffect::FlowchartNavigationEnded,
        &mut scene,
        &app_state,
        &mut keys,
        &mut env,
    );
    assert_eq!(op, Some(FlowchartOperation::NavigationEnded));
    assert!(!app.navigator.is_exploring);
    assert!(!keys.is_exploring);

    // a walk that ends on the keyup that commits: after_key_up clears it
    app.answer(&navigate("a"), &mut scene, &app_state, &mut keys, &mut env);
    assert!(app.navigator.is_exploring);
    keys.is_exploring = false;
    app.after_key_up(&keys);
    assert!(!app.navigator.is_exploring);
}
